export interface FileAction {
  path: string;
  status: "writing" | "done" | "deleted";
}

export type Part =
  | { kind: "text"; text: string }
  | { kind: "plan"; text: string }
  | { kind: "shell"; command: string }
  | { kind: "file"; path: string; status: FileAction["status"] };

export interface ChatMessage {
  id: string;
  role: "user" | "assistant";
  /** What the model sees/said (raw reply for assistant). */
  content: string;
  images?: string[];
  /** auto-fix messages generated by the system, not typed by the user */
  auto?: boolean;
  error?: string;
  // assistant display data
  parts?: Part[];
  model?: string;
  skills?: string[];
  pending?: boolean;
  /** project files right after this assistant step (for version restore) */
  snapshot?: Record<string, string>;
  createdAt: number;
}

export interface Project {
  id: string;
  name: string;
  files: Record<string, string>;
  messages: ChatMessage[];
  pendingPrompt?: { text: string; images?: string[] };
  createdAt: number;
  updatedAt: number;
}
